  el('resetDemo').textContent = t(state.lang, 'reset');
  el('scenarioLabel').textContent = t(state.lang, 'scenarioLabel');
  el('policyLabel').textContent = t(state.lang, 'policyLabel');
  fillSelect(el('roleSelect'), resources[state.lang].roles, state.role);
  fillSelect(el('scenarioSelect'), resources[state.lang].scenarios, state.scenario);
  fillSelect(el('policySelect'), resources[state.lang].policies, state.policy);
