function passportSectionLabel(section) {
  const fr = { identity:'Identité minimale', activity:'Activité économique', confidence:'Confiance des données', incluscore:'INCLUSCORE', financialHealth:'Santé financière', debtRisk:'Risque de surendettement', recommendation:'Recommandation non contraignante', humanDecision:'Décision humaine', engineVersions:'Versions des moteurs', limitations:'Limites et garde-fous' };
  const en = { identity:'Minimal identity', activity:'Economic activity', confidence:'Data confidence', incluscore:'INCLUSCORE', financialHealth:'Financial health', debtRisk:'Over-indebtedness risk', recommendation:'Non-binding recommendation', humanDecision:'Human decision', engineVersions:'Engine versions', limitations:'Limits and safeguards' };
  return (state.lang === 'fr' ? fr : en)[section] || tokenText(section);
}
function passportMatrix(token='') {
  const clean = String(token).replace(/[^0-9a-f]/gi,'') || '0123456789abcdef';
  const cells=[];
  for(let i=0;i<289;i++) {
    const a=parseInt(clean[i%clean.length],16), b=parseInt(clean[(i*7+3)%clean.length],16);
    const finder=(i%17<5&&Math.floor(i/17)<5)||(i%17>11&&Math.floor(i/17)<5)||(i%17<5&&Math.floor(i/17)>11);
    cells.push(`<i class="${finder || ((a+b+i)%3===0) ? 'on':''}"></i>`);
  }
  return `<div class="verification-matrix" aria-label="${state.lang === 'fr' ? 'Matrice de vérification' : 'Verification matrix'}">${cells.join('')}</div>`;
}
function downloadJson(filename, value) {
  const blob = new Blob([JSON.stringify(value, null, 2)], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a'); link.href=url; link.download=filename; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 500);
}
function downloadText(filename, value, type='text/plain;charset=utf-8') {
  const blob = new Blob([String(value ?? '')], { type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a'); link.href=url; link.download=filename; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 500);
}

function getCaseContext(results) {
  return loadPersistedCase(results.recommendation.referenceId) || {
    recommendationReference:results.recommendation.referenceId,
    workflow:results.workflow,
    decision:results.humanDecision,
    appeal:results.appeal,
    message:null
  };
}
function setCaseMessage(context, message, tone='success') {
  context.message = { text:message, tone, at:new Date().toISOString() };
  savePersistedCase(context);
}
function actionReason(id, fallback) {
  return String(el(id)?.value || fallback || '').trim();
}
